// math (x front-left, y right, z up)  →  three.js (y-up)
const V = (x, y, z = 0) => new THREE.Vector3(y, z, x);
function remapXY(geom, z) {            // geometry authored in math-XY plane
  const p = geom.attributes.position;
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), y = p.getY(i);
    p.setXYZ(i, y, z, x);
  }
  p.needsUpdate = true; geom.computeVertexNormals(); geom.computeBoundingSphere();
  return geom;
}

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xdcdcdc, 0.95));
const dl = new THREE.DirectionalLight(0xffffff, 0.45); dl.position.set(5, 8, 6); scene.add(dl);

/* ── region R ───────────────────────────────────────────────────────────── */
const XC = 1.2, YC = 1.2;
const rTheta = t => 1.05 + 0.18 * Math.cos(2 * t) - 0.30 * Math.cos(t);
const inside = (x, y) => Math.hypot(x - XC, y - YC) <= rTheta(Math.atan2(y - YC, x - XC));
const NB = 220, bnd = [];
for (let i = 0; i < NB; i++) { const t = 2 * Math.PI * i / NB, r = rTheta(t); bnd.push([XC + r * Math.cos(t), YC + r * Math.sin(t)]); }

/* ── state ──────────────────────────────────────────────────────────────── */
let F = (x, y) => 2.6 - 0.3 * ((x - 1.2) ** 2 + (y - 1.2) ** 2);
let n = 6, sx = 1.2, sy = 1.15, showAll = false, riemann = 0, cellCount = 0;
const GX0 = -0.4, GY0 = -0.2, GSPAN = 2.8;
const SX0 = -0.4, SX1 = 2.8, SY0 = -0.4, SY1 = 3.2;
const sfz = (x, y) => { let v; try { v = F(x, y); } catch (e) { v = NaN; }
  if (!Number.isFinite(v)) v = 0; return Math.max(-1.0, Math.min(4.2, v)); };

/* ── axes ───────────────────────────────────────────────────────────────── */
const blackMat = new THREE.MeshLambertMaterial({ color: 0x1a1a1a });
function axisArrow(dirM, len) {
  const g = new THREE.Group();
  const dir = V(...dirM).normalize();
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  const sl = len - 0.24;
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, sl, 14), blackMat);
  shaft.quaternion.copy(q); shaft.position.copy(dir.clone().multiplyScalar(sl / 2));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.105, 0.26, 18), blackMat);
  head.quaternion.copy(q); head.position.copy(dir.clone().multiplyScalar(sl + 0.13));
  g.add(shaft, head); scene.add(g); return g;
}
axisArrow([1, 0, 0], 3.2); axisArrow([0, 1, 0], 4.2); axisArrow([0, 0, 1], 3.6);

/* ── xy-plane patch outline ─────────────────────────────────────────────── */
const patch = new THREE.LineLoop(
