fillMesh.renderOrder = 1; scene.add(fillMesh);
const bCurve = new THREE.CatmullRomCurve3(bnd.map(p => V(p[0], p[1], 0.012)), true);
const outline = new THREE.Mesh(new THREE.TubeGeometry(bCurve, 320, 0.04, 10, true),
  new THREE.MeshLambertMaterial({ color: 0x0fa37f }));
outline.renderOrder = 2; scene.add(outline);

