    const c = [[cx - h / 2, cy - h / 2], [cx + h / 2, cy - h / 2], [cx + h / 2, cy + h / 2], [cx - h / 2, cy + h / 2]];
    for (let e = 0; e < 4; e++) {
      tops.push(V(c[e][0], c[e][1], zt), V(c[(e + 1) % 4][0], c[(e + 1) % 4][1], zt));
