function buildPartition() {
  const h = GSPAN / n, pts = [], M = 240, z = 0.006;
  for (let i = 0; i <= n; i++) {
    const x = GX0 + i * h; let run = null;
    for (let k = 0; k <= M; k++) {
      const y = GY0 + GSPAN * k / M, ins = inside(x, y);
      if (ins && run === null) run = y;
      if ((!ins || k === M) && run !== null) { pts.push(V(x, run, z), V(x, y, z)); run = null; }
    }
    const y0 = GY0 + i * h; run = null;
    for (let k = 0; k <= M; k++) {
      const xx = GX0 + GSPAN * k / M, ins = inside(xx, y0);
      if (ins && run === null) run = xx;
      if ((!ins || k === M) && run !== null) { pts.push(V(run, y0, z), V(xx, y0, z)); run = null; }
    }
