  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, sl, 14), blackMat);
  shaft.quaternion.copy(q); shaft.position.copy(dir.clone().multiplyScalar(sl / 2));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.105, 0.26, 18), blackMat);
  head.quaternion.copy(q); head.position.copy(dir.clone().multiplyScalar(sl + 0.13));
  g.add(shaft, head); scene.add(g); return g;
}
axisArrow([1, 0, 0], 3.2); axisArrow([0, 1, 0], 4.2); axisArrow([0, 0, 1], 3.6);

/* ── xy-plane patch outline ─────────────────────────────────────────────── */
const patch = new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints([V(-0.6, -0.4, 0), V(-0.6, 3.2, 0), V(3.0, 3.2, 0), V(3.0, -0.4, 0)]),
  new THREE.LineBasicMaterial({ color: 0xc8c8c8 }));
patch.renderOrder = 0; scene.add(patch);

/* ── region fill + thick outline ────────────────────────────────────────── */
const shp = new THREE.Shape(bnd.map(p => new THREE.Vector2(p[0], p[1])));
const fillMesh = new THREE.Mesh(remapXY(new THREE.ShapeGeometry(shp, 64), 0.004),
  new THREE.MeshBasicMaterial({ color: 0xd6ecea, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false }));
fillMesh.renderOrder = 1; scene.add(fillMesh);
const bCurve = new THREE.CatmullRomCurve3(bnd.map(p => V(p[0], p[1], 0.012)), true);
const outline = new THREE.Mesh(new THREE.TubeGeometry(bCurve, 340, 0.04, 10, true),
  new THREE.MeshLambertMaterial({ color: 0x0fa37f }));
outline.renderOrder = 2; scene.add(outline);

/* ── partition grid ─────────────────────────────────────────────────────── */
const gridLines = new THREE.LineSegments(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: 0x9aa5a5, transparent: true, opacity: 0.6 }));
gridLines.renderOrder = 2; scene.add(gridLines);

/* ── surface + rim ──────────────────────────────────────────────────────── */
const surfMat = new THREE.MeshLambertMaterial({ color: 0x8ec9c3, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false });
const surf = new THREE.Mesh(new THREE.BufferGeometry(), surfMat); surf.renderOrder = 5; scene.add(surf);
const rim = new THREE.LineLoop(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x5aa8a0 }));
rim.renderOrder = 5; scene.add(rim);

/* ── cylinder over R (wall + top rim + spokes) ──────────────────────────── */
const cylGroup = new THREE.Group(); scene.add(cylGroup);
const wall = new THREE.Mesh(new THREE.BufferGeometry(),
  new THREE.MeshBasicMaterial({ color: 0xdbe3e7, transparent: true, opacity: 0.28, side: THREE.DoubleSide, depthWrite: false }));
wall.renderOrder = 4; cylGroup.add(wall);
const wallRim = new THREE.LineLoop(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: 0x9fb1b8, transparent: true, opacity: 0.9 }));
wallRim.renderOrder = 4; cylGroup.add(wallRim);
const wallSpokes = new THREE.LineSegments(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: 0xb6c3c8, transparent: true, opacity: 0.45 }));
wallSpokes.renderOrder = 4; cylGroup.add(wallSpokes);

/* ── all-columns (Riemann sum) ──────────────────────────────────────────── */
const allMat = new THREE.MeshLambertMaterial({ color: 0xf2a349, transparent: true, opacity: 0.40, depthWrite: false });
const allCols = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1), allMat, MAXI);
allCols.renderOrder = 6; allCols.count = 0; allCols.visible = false; scene.add(allCols);
const allTops = new THREE.LineSegments(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: 0xd9822b, transparent: true, opacity: 0.7 }));
allTops.renderOrder = 6; allTops.visible = false; scene.add(allTops);

/* ── representative column ──────────────────────────────────────────────── */
const colBox = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshLambertMaterial({ color: 0xf2a349, transparent: true, opacity: 0.5, depthWrite: false }));
colBox.renderOrder = 7; scene.add(colBox);
const colEdges = new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(1, 1, 1)),
  new THREE.LineBasicMaterial({ color: 0xd9822b })); colEdges.renderOrder = 7; scene.add(colEdges);
const colTop = new THREE.Mesh(new THREE.PlaneGeometry(1, 1),
  new THREE.MeshBasicMaterial({ color: 0xe8952f, transparent: true, opacity: 0.85, side: THREE.DoubleSide, depthWrite: false }));
colTop.rotation.x = -Math.PI / 2; colTop.renderOrder = 7; scene.add(colTop);

/* ── red dots + dashed height ───────────────────────────────────────────── */
const redMat = new THREE.MeshLambertMaterial({ color: 0xe33127 });
const dotA = new THREE.Mesh(new THREE.SphereGeometry(0.07, 18, 14), redMat); dotA.renderOrder = 9; scene.add(dotA);
const dotB = new THREE.Mesh(new THREE.SphereGeometry(0.07, 18, 14), redMat); dotB.renderOrder = 9; scene.add(dotB);
const dash = new THREE.Line(new THREE.BufferGeometry(),
  new THREE.LineDashedMaterial({ color: 0xe33127, dashSize: 0.12, gapSize: 0.09 }));
dash.renderOrder = 9; scene.add(dash);
const grabHit = new THREE.Mesh(new THREE.SphereGeometry(0.24, 12, 10),
  new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })); scene.add(grabHit);

/* ── leader arrows ──────────────────────────────────────────────────────── */
const leadMat = new THREE.LineBasicMaterial({ color: 0x111111 });
const leadHeadMat = new THREE.MeshLambertMaterial({ color: 0x111111 });
function makeLeader() {
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]), leadMat);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.17, 12), leadHeadMat);
  line.renderOrder = 10; cone.renderOrder = 10; scene.add(line, cone); return { line, cone };
}
function setLeader(L, tailM, tipM) {
  const tail = V(...tailM), tip = V(...tipM);
  const dir = tip.clone().sub(tail).normalize();
  L.line.geometry.dispose();
  L.line.geometry = new THREE.BufferGeometry().setFromPoints([tail, tip.clone().sub(dir.clone().multiplyScalar(0.17))]);
  L.cone.position.copy(tip.clone().sub(dir.clone().multiplyScalar(0.085)));
  L.cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
}
const LHeight = makeLeader(), LVol = makeLeader(), LArea = makeLeader(), LPt = makeLeader();
// tails chosen so text lands where the source puts it (right / lower-right / lower-left / bottom)
const TAIL_H = [0.20, 3.30, 3.00],
      TAIL_V = [0.40, 3.60, -0.70],
      TAIL_A = [2.60, 0.76, -1.10],
      TAIL_P = [1.60, 2.45, -1.00];

/* ── builders ───────────────────────────────────────────────────────────── */
function buildSurface() {
  const NX = 80, NY = 80, pos = [], idx = [];
  for (let i = 0; i <= NX; i++) {
    const x = SX0 + (SX1 - SX0) * i / NX;
    for (let j = 0; j <= NY; j++) {
      const y = SY0 + (SY1 - SY0) * j / NY;
      pos.push(y, sfz(x, y), x);
    }
  }
  for (let i = 0; i < NX; i++) for (let j = 0; j < NY; j++) {
    const a = i * (NY + 1) + j, b = a + 1, c = a + NY + 1, e = c + 1;
    idx.push(a, c, b, b, c, e);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx); g.computeVertexNormals(); g.computeBoundingSphere();
  surf.geometry.dispose(); surf.geometry = g;

  const rp = [], M = 44;
  for (let i = 0; i <= M; i++) { const x = SX0 + (SX1 - SX0) * i / M; rp.push(V(x, SY0, sfz(x, SY0))); }
  for (let j = 1; j <= M; j++) { const y = SY0 + (SY1 - SY0) * j / M; rp.push(V(SX1, y, sfz(SX1, y))); }
  for (let i = M - 1; i >= 0; i--) { const x = SX0 + (SX1 - SX0) * i / M; rp.push(V(x, SY1, sfz(x, SY1))); }
  for (let j = M - 1; j >= 1; j--) { const y = SY0 + (SY1 - SY0) * j / M; rp.push(V(SX0, y, sfz(SX0, y))); }
  rim.geometry.dispose(); rim.geometry = new THREE.BufferGeometry().setFromPoints(rp);
}

function buildWall() {
  const pos = [], idx = [], rimPts = [], spokes = [];
  for (let i = 0; i < NB; i++) {
    const [bx, by] = bnd[i], zt = Math.max(0.08, sfz(bx, by));
    pos.push(by, 0, bx, by, zt, bx);
    rimPts.push(V(bx, by, zt));
    if (i % 12 === 0) spokes.push(V(bx, by, 0.01), V(bx, by, zt));
  }
  for (let i = 0; i < NB; i++) {
    const a = 2 * i, b = a + 1, c = (2 * ((i + 1) % NB)), e = c + 1;
    idx.push(a, c, b, b, c, e);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx); g.computeVertexNormals(); g.computeBoundingSphere();
  wall.geometry.dispose(); wall.geometry = g;
  wallRim.geometry.dispose(); wallRim.geometry = new THREE.BufferGeometry().setFromPoints(rimPts);
  wallSpokes.geometry.dispose(); wallSpokes.geometry = new THREE.BufferGeometry().setFromPoints(spokes);
}

function buildPartition() {
  const h = GSPAN / n, pts = [], M = 240, z = 0.006;
  for (let i = 0; i <= n; i++) {
    const x = GX0 + i * h; let run = null;
    for (let k = 0; k <= M; k++) {
      const y = GY0 + GSPAN * k / M, ins = inside(x, y);
      if (ins && run === null) run = y;
      if ((!ins || k === M) && run !== null) { pts.push(V(x, run, z), V(x, y, z)); run = null; }
    }
    const y0 = GY0 + i * h; run = null;
    for (let k = 0; k <= M; k++) {
      const xx = GX0 + GSPAN * k / M, ins = inside(xx, y0);
      if (ins && run === null) run = xx;
      if ((!ins || k === M) && run !== null) { pts.push(V(run, y0, z), V(xx, y0, z)); run = null; }
    }
  }
  gridLines.geometry.dispose();
  gridLines.geometry = new THREE.BufferGeometry().setFromPoints(pts);

  // all columns (Riemann sum)
  const mtx = new THREE.Matrix4(), q = new THREE.Quaternion(), tops = [];
  let k = 0; riemann = 0;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    const cx = GX0 + (i + 0.5) * h, cy = GY0 + (j + 0.5) * h;
    if (!inside(cx, cy)) continue;
    const fv = sfz(cx, cy), zt = Math.max(0.02, fv);
    riemann += fv * h * h;
    if (k < MAXI) {
      mtx.compose(V(cx, cy, zt / 2), q, new THREE.Vector3(h, zt, h));
      allCols.setMatrixAt(k, mtx);
      const c = [[cx - h / 2, cy - h / 2], [cx + h / 2, cy - h / 2], [cx + h / 2, cy + h / 2], [cx - h / 2, cy + h / 2]];
      for (let e = 0; e < 4; e++) tops.push(V(c[e][0], c[e][1], zt), V(c[(e + 1) % 4][0], c[(e + 1) % 4][1], zt));
    }
    k++;
  }
  cellCount = k;
  allCols.count = Math.min(k, MAXI);
  allCols.instanceMatrix.needsUpdate = true;
  allTops.geometry.dispose();
  allTops.geometry = new THREE.BufferGeometry().setFromPoints(tops);
}

function updateColumn() {
  const h = GSPAN / n;
  const i = Math.floor((sx - GX0) / h), j = Math.floor((sy - GY0) / h);
  const cx = GX0 + (i + 0.5) * h, cy = GY0 + (j + 0.5) * h;
  const zt = Math.max(0.12, sfz(sx, sy));
  colBox.scale.set(h, zt, h); colBox.position.copy(V(cx, cy, zt / 2));
  colEdges.scale.copy(colBox.scale); colEdges.position.copy(colBox.position);
  colTop.scale.set(h, h, 1); colTop.position.copy(V(cx, cy, zt + 0.006));
  dotA.position.copy(V(sx, sy, 0.05));
  dotB.position.copy(V(sx, sy, zt));
  grabHit.position.copy(dotA.position);
  dash.geometry.dispose();
  dash.geometry = new THREE.BufferGeometry().setFromPoints([V(sx, sy, 0.05), V(sx, sy, zt)]);
  dash.computeLineDistances();
  return { cx, cy, zt, h };
}

/* ── build everything once ──────────────────────────────────────────────── */
buildSurface(); buildWall(); buildPartition(); updateColumn();

function updateAnnotations() {
  const h = GSPAN / n, zt = Math.max(0.12, sfz(sx, sy));
  setLeader(LHeight, TAIL_H, [sx, sy, zt * 0.55]);
  setLeader(LVol, TAIL_V, [sx, sy + h / 2, zt * 0.42]);
  setLeader(LArea, TAIL_A, [sx - h * 0.35, sy - h * 0.35, 0.03]);
  setLeader(LPt, TAIL_P, [sx, sy, 0.08]);
}
updateAnnotations();

/* ── camera ─────────────────────────────────────────────────────────────── */
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.68 });
document.getElementById('btnReset').style.display = '';

/* ── labels (text only — all numbers live in the readout panel) ─────────── */
addLabel('<i>x</i>', V(3.45, 0, 0), { fontSize: '17px', offset: [-6, 16] });
addLabel('<i>y</i>', V(0, 4.45, 0), { fontSize: '17px', offset: [12, -8] });
addLabel('<i>z</i>', V(0, 0, 3.82), { fontSize: '17px', offset: [15, -6] });
addLabel('<i>z</i> = <i>f</i>(<i>x</i>, <i>y</i>)', V(0.0, 2.6, 3.30), { fontSize: '16px' });
const K = 'x<sub>k</sub><sup>*</sup>', KY = 'y<sub>k</sub><sup>*</sup>';
addLabel(`Height<br><i>f</i>(${K}, ${KY})`, V(...TAIL_H), { fontSize: '15px', offset: [62, -6] });
addLabel(`Volume<br><i>f</i>(${K}, ${KY})&Delta;A<sub>k</sub>`, V(...TAIL_V), { fontSize: '15px', offset: [74, 10] });
addLabel('Area &Delta;A<sub>k</sub>', V(...TAIL_A), { fontSize: '15px', offset: [-44, 12] });
addLabel(`(${K}, ${KY})`, V(...TAIL_P), { fontSize: '15px', offset: [36, 14] });

/* ── readout ────────────────────────────────────────────────────────────── */
const readout = document.getElementById('readout');
function updateReadout() {
  const h = GSPAN / n, dA = h * h, fv = sfz(sx, sy);
  let html = `(${K}, ${KY}) = (<b>${sx.toFixed(2)}</b>, <b>${sy.toFixed(2)}</b>)<br>` +
    `<i>f</i>(${K}, ${KY}) = <b>${fv.toFixed(3)}</b><br>` +
    `&Delta;A<sub>k</sub> = (2.8/${n})<sup>2</sup> = <b>${dA.toFixed(3)}</b><br>` +
    `<i>f</i>&middot;&Delta;A<sub>k</sub> = <b>${(fv * dA).toFixed(3)}</b>`;
  if (showAll) html += `<br>&Sigma; <i>f</i>&middot;&Delta;A<sub>k</sub> = <b>${riemann.toFixed(3)}</b> &nbsp;(${cellCount} cells)`;
  readout.innerHTML = html;
}
updateReadout();

/* ── interactivity: explanations ────────────────────────────────────────── */
registerInteractive(colBox, {
  title: 'One approximating parallelepiped',
  tooltip: 'Volume = f(xk*, yk*) · ΔAk',
  body: 'Its base is one subrectangle of area ΔAk inside R, and its height is the value of f at the sample point (xk*, yk*). Its volume f(xk*,yk*)·ΔAk is a single term of the Riemann sum.'
});
registerInteractive(fillMesh, {
  title: 'Region R',
  tooltip: 'The region of integration R',
  body: 'R is partitioned into subrectangles. Only the cells lying inside R contribute to the Riemann sum Σ f(xk*,yk*)ΔAk.'
});
registerInteractive(surf, {
  title: 'Surface z = f(x, y)',
  tooltip: 'The integrand as a surface',
  body: 'The height of every column is read off this surface. The double integral ∬R f dA is the limit of the Riemann sums as all ΔAk → 0.'
});
registerInteractive(wall, {
  title: 'Cylinder over R',
  tooltip: 'Boundary of R swept straight up to the surface',
  body: 'Sweeping the boundary curve of R vertically up to z = f(x, y) bounds the solid whose volume the double integral measures. Every approximating column lives inside this cylinder.'
});

/* ── equation input ─────────────────────────────────────────────────────── */
const eq = bindEquationInput('fEq', (fn) => {
  F = fn; buildSurface(); buildWall(); buildPartition(); updateColumn();
  updateAnnotations(); updateReadout();
}, { variables: ['x', 'y'] });

/* ── partition slider ───────────────────────────────────────────────────── */
const nSlider = document.getElementById('nSlider'), nOut = document.getElementById('nOut');
function setN(v) {
  n = v; nSlider.value = String(v); nOut.textContent = String(v);
  buildPartition(); updateColumn(); updateAnnotations(); updateReadout();
}
nSlider.addEventListener('input', () => setN(parseInt(nSlider.value, 10)));

/* ── column display toggle ──────────────────────────────────────────────── */
const bS = document.getElementById('btnSingle'), bA = document.getElementById('btnAll');
function setMode(all) {
  showAll = all;
  allCols.visible = all; allTops.visible = all;
  bS.classList.toggle('active', !all); bA.classList.toggle('active', all);
  updateReadout();
}
bS.addEventListener('click', () => setMode(false));
bA.addEventListener('click', () => setMode(true));

/* ── cylinder visibility ────────────────────────────────────────────────── */
const chkCyl = document.getElementById('chkCyl');
chkCyl.addEventListener('change', () => { cylGroup.visible = chkCyl.checked; });

/* ── drag the sample point ──────────────────────────────────────────────── */
const rc = new THREE.Raycaster(), ptr = new THREE.Vector2();
const zPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
let dragging = false;
function clampToR(x, y) {
  const dx = x - XC, dy = y - YC, th = Math.atan2(dy, dx), r = Math.hypot(dx, dy);
  const Rm = rTheta(th) * 0.92;
  return r > Rm ? [XC + Math.cos(th) * Rm, YC + Math.sin(th) * Rm] : [x, y];
}
function setPtr(e) {
  const b = canvas.getBoundingClientRect();
  ptr.x = ((e.clientX - b.left) / b.width) * 2 - 1;
  ptr.y = -((e.clientY - b.top) / b.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', e => {
  setPtr(e); rc.setFromCamera(ptr, camera);
  if (rc.intersectObject(grabHit, false).length) {
    dragging = true; controls.enabled = false; canvas.style.cursor = 'grabbing';
    try { canvas.setPointerCapture(e.pointerId); } catch (err) { }
  }
});
canvas.addEventListener('pointermove', e => {
  if (!dragging) return;
  setPtr(e); rc.setFromCamera(ptr, camera);
  const hit = new THREE.Vector3();
  if (rc.ray.intersectPlane(zPlane, hit)) {
    const p = clampToR(hit.z, hit.x);
    sx = p[0]; sy = p[1];
