  }
});
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; canvas.style.cursor = 'default'; }
});

/* ── sample-point tween ─────────────────────────────────────────────────── */
let tween = null;
function tweenSample(tx, ty, dur) { tween = { x0: sx, y0: sy, tx, ty, t0: performance.now(), dur }; }
(function tick() {
  requestAnimationFrame(tick);
  if (!tween) return;
  const t = Math.min(1, (performance.now() - tween.t0) / tween.dur);
  const e = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
  sx = tween.x0 + (tween.tx - tween.x0) * e;
  sy = tween.y0 + (tween.ty - tween.y0) * e;
