/* ── guided steps ───────────────────────────────────────────────────────── */
const steps = [
  { t: 'One representative column',
    d: 'The bean-shaped region R is partitioned into subrectangles. One of them, of area ΔA<sub>k</sub>, carries an orange box whose height is the surface value f(x<sub>k</sub>*, y<sub>k</sub>*) at the red sample point, so its volume is f(x<sub>k</sub>*, y<sub>k</sub>*)·ΔA<sub>k</sub>.',
    go() { setN(6); setMode(false); tweenSample(1.2, 1.15, 600); } },
  { t: 'Move the sample point',
    d: 'Drag the red dot to another subrectangle: the column jumps there and its height changes to the surface value directly above the new point.',
    go() { setN(6); setMode(false); tweenSample(1.85, 1.75, 1500); } },
  { t: 'Sum over all subrectangles',
    d: 'Every subrectangle inside R gets its own column. Their total volume Σ f(x<sub>k</sub>*,y<sub>k</sub>*)ΔA<sub>k</sub> is a coarse estimate of the volume under z = f(x, y) inside the pale cylinder.',
    go() { setN(6); setMode(true); } },
  { t: 'Refine the partition',
    d: 'As n grows, each ΔA<sub>k</sub> shrinks and the staircase of columns converges to the smooth solid under the surface — the double integral.',
    go() { setN(14); setMode(true); } },
  { t: 'Change the integrand',
    d: 'Type a new f(x, y). The teal surface redraws and every column height, including the labeled f(x<sub>k</sub>*, y<sub>k</sub>*), follows the new integrand.',
    go() { setN(10); setMode(true);
      const inp = document.getElementById('fEq');
      inp.value = '2.3 + 0.5*sin(1.6*x)*cos(1.4*y)';
      eq.apply(inp.value); } }
];
let si = 0;
const stT = document.getElementById('stepTitle'), stD = document.getElementById('stepText');
function goToStep(i) {
  si = (i + steps.length) % steps.length;
  stT.innerHTML = `${si + 1}. ${steps[si].t}`;
  stD.innerHTML = steps[si].d;
  steps[si].go();
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(si + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(si - 1));
goToStep(0);
// @FIGURE_CODE_END

